		t.Fatalf("want empty non-nil list, got %v", impacts)
	}

	impacts, err = Impacts(graph, "p")
	if err != nil {
		t.Fatalf("Impacts(p): %v", err)
	}
	if got, want := impactNames(impacts), []string{"c"}; !reflect.DeepEqual(got, want) {
